int changes = 0;
int prev_dir = 0;   // -1 = down, +1 = up

// Skip first element
for (int i = 1; i < n; i++) {
    int dir = 0;

    if (arr[i] > arr[i - 1]) dir = 1;
    else if (arr[i] < arr[i - 1]) dir = -1;

    if (dir != 0) {
        if (prev_dir != 0 && dir != prev_dir) changes++;
        prev_dir = dir;
    }
}
```

